typedef struct LNode {
    int data;
    struct LNode *link;
} *LinkList;

int Search_k(LinkList list, int k) {
    if (k <= 0) return 0;
    LinkList p = list->link, q = list->link;  // 初始指向第一个结点
    int count = 0;
    while (p != NULL) {
        if (count < k) {       // p先前进k步
            p = p->link;
            count++;
        } else {               // 之后p和q同步前进
            p = p->link;
            q = q->link;
        }
    }
    if (count == k) {          // 链表长度≥k
        printf("%d", q->data);
        return 1;
    }
    return 0;                  // k超出链表长度
}

